#!/usr/bin/env python3
"""Render the certified N19 second-order algebraic construction offline."""
from pathlib import Path
import json,html,re
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
def tex(value,display=False):
 tag='div' if display else 'span'
 return '<'+tag+' class="math" data-tex="'+html.escape(value,quote=True)+'"'+(' data-display="true"' if display else '')+'></'+tag+'>'
def main():
 state=json.loads((HERE/'basis.json').read_text());cert=json.loads((HERE/'certificate.json').read_text())
 assert json.loads((HERE/'verification.json').read_text())['passed']
 css=re.search(r'<style>(.*?)</style>',(ROOT/'research/t2-spin2-inertia/index.html').read_text(),re.S).group(1)
 css='\n'.join(line.rstrip() for line in css.split('\n'))
 css+=' .formula-card{background:#fffef9;border:1px solid #deddd3;padding:1.3rem;margin:1.5rem 0;border-radius:5px}.scroll-table{overflow-x:auto;max-width:100%}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid #deddd3;padding:.55rem}.coordinate{white-space:nowrap;font-size:.76rem}.downloads{display:grid;grid-template-columns:1fr 1fr;gap:.6rem 1.4rem}nav{display:flex;gap:1.1rem;flex-wrap:wrap;margin:1.5rem 0}details{margin:1.3rem 0}summary{cursor:pointer}code{overflow-wrap:anywhere}@media(max-width:600px){.downloads{grid-template-columns:1fr}}'
 body='''<p class="eyebrow">Anticoherent subspaces · Exact algebraic basis</p><a class="back-link" href="../../index.html#n=19&amp;t=2&amp;subspace=algebraic-n19-k4-t2">← Return to the catalogue</a><h1>Nineteen qubits at second order</h1><p class="lead">Four analytical Dicke vectors attain the maximum AC-subspace dimension. Their coefficients are defined by a unique real algebraic root in an explicit rational box, with a complete existence certificate.</p><div class="result"><strong>Proved maximum dimension</strong>'''+tex(r'\boxed{K(19,2)=4}',True)+'''<p>Every normalized complex superposition in the displayed span is second-order AC.</p></div><nav aria-label="On this page"><a href="#basis">Analytical basis</a><a href="#root">Exact coefficient definition</a><a href="#proof">Existence and optimality</a><a href="#source">Source and files</a></nav><section id="basis"><h2>A basis on four residue classes</h2><p>Use normalized Dicke states. Define ten complex amplitudes from eighteen real algebraic coordinates:</p>'''+tex(state['derivationLatex'],True)+tex(state['parameterLatex'],True)+'''<div class="formula-card">'''+tex(r'\begin{aligned}|u_1\rangle&=\sum_{j=0}^4a_j|D_{19}^{(4j)}\rangle,&|u_2\rangle&=\sum_{j=0}^4b_j|D_{19}^{(4j+1)}\rangle,\\|u_3\rangle&=\sum_{j=0}^4b_j|D_{19}^{(18-4j)}\rangle,&|u_4\rangle&=\sum_{j=0}^4a_j|D_{19}^{(19-4j)}\rangle.\end{aligned}',True)+'''<p>The last two vectors are unitary reversals of the first two. There is no complex conjugation in these reversal formulas. Every unlisted Dicke coefficient is zero.</p></div><p><a href="../../index.html#n=19&amp;t=2&amp;subspace=algebraic-n19-k4-t2">Inspect each exact vector and Majorana sphere ↗</a> · <a href="basis.json">Download all analytical coefficients ↓</a></p><p>The unique-root definition below is exact. A shorter expression in radicals has not been established.</p></section><section id="root"><h2>Exact coefficient definition</h2><p>Write each displayed coefficient as</p>'''+tex(r'c_{a,r}=\sqrt{\binom{19}{r}}\,\xi_{a,r},\qquad h_0(r)=1,\quad h_1(r)=19-2r,\quad h_2(r)=3(19-2r)^2-399.',True)+'''<p>The nonzero scaled coefficients are</p>'''+tex(r'\begin{aligned}\xi_{1,4j}=\xi_{4,19-4j}&=A_j+iB_j,\\\xi_{2,4j+1}=\xi_{3,18-4j}&=C_j+iD_j.\end{aligned}',True)+'''<p>Define the complex quadratic polynomials</p>'''+tex(r'P_{ab}^{q,p}(x)=\sum_{r=q}^{19}\binom{19}{r}\,r^{\underline q}h_p(r)\overline{\xi_{a,r-q}}\xi_{b,r}-\delta_{q0}\delta_{p0}\delta_{ab},',True)+'''<p>where the falling factorial is one for zero raising power. Each of the eighteen real equations below selects a real or imaginary part of one polynomial.</p><details><summary>The eighteen defining equations</summary><div class="scroll-table"><table><thead><tr><th>Equation</th><th>Basis pair</th><th>Raising power q</th><th>Moment p</th><th>Part</th></tr></thead><tbody>'''
 for i,e in enumerate(cert['equations'],1):
  body+='<tr><td>'+tex('F_{'+str(i)+'}=0')+'</td><td>'+str(e['basisPair'][0]+1)+', '+str(e['basisPair'][1]+1)+'</td><td>'+str(e['raisingPower'])+'</td><td>'+str(e['zPower'])+'</td><td>'+e['part']+'</td></tr>'
 body+='''</tbody></table></div><p>The coefficient lists and the exact rational reconstruction of every remaining physical equation are included in <a href="certificate.json">the certificate</a>.</p></details><p>The coordinates are the <strong>unique real zero</strong> of those equations in the box</p>'''+tex(r'|x_i-x_i^{(0)}|\le10^{-50},\qquad x_i^{(0)}=\frac{n_i}{10^{70}},\qquad i=1,\ldots,18.',True)+'''<details><summary>Exact rational center of the isolating box</summary><p>These integers specify the box center; they are not rounded substitutions for the exact root.</p><div class="scroll-table"><table><thead><tr><th>i</th><th>Integer numerator nᵢ</th></tr></thead><tbody>'''
 for i,slot in enumerate(cert['unknownSlotIndices'],1):body+='<tr><td>'+str(i)+'</td><td class="coordinate">'+cert['fullCenterNumerators'][slot]+'</td></tr>'
 body+='''</tbody></table></div></details></section><section id="proof"><h2>Why an exact root exists</h2><p>A rational matrix preconditions the eighteen equations. For the map</p>'''+tex(r'G(x)=x-AF(x)',True)+'''<p>integer and rational arithmetic proves that the box maps strictly into itself and that the map is a contraction:</p>'''+tex(r'\begin{aligned}\operatorname{Lip}(G)&<7\times10^{-43},\\\|G(x)-x^{(0)}\|_\infty&<6\times10^{-71}<10^{-50}.\end{aligned}',True)+'''<p>The contraction theorem gives one and only one root in the box. The preconditioning matrix is invertible, so a fixed point solves every defining equation. These proof inequalities use exact fractions; the numerical search only located the box.</p><h2>The entire complex span is AC</h2><p>One verifier reconstructs the physical Gram and spin-moment equations. A separate verifier derives all reduced-state entries directly from normalized Dicke splitting. Both certify</p>'''+tex(r'R_2(|u_a\rangle\langle u_b|)=\delta_{ab}\frac{I_3}{3},\qquad 1\le a,b\le4.',True)+'''<p>This checks all 144 complex entries, including all cross terms between different basis vectors. It establishes anticoherence for every normalized superposition in the four-dimensional span.</p><h2>Why dimension four is maximal</h2><p>The general auxiliary-spin inertia bound applies to every complex second-order AC subspace:</p>'''+tex(r'4k\le N-2=17\quad\Longrightarrow\quad k\le4.',True)+'''<p>The analytical construction attains this bound. No residue-class or symmetry assumption is imposed on a competing subspace. <a href="../ancilla-inertia/index.html">Read the general upper-bound proof ↗</a></p></section><section id="source"><h2>Relation to the supplied Julia example</h2><p>The starting point is <a href="../../references/ACLiege.jl">Π_19_4_2 in ACLiege.jl, line 1006</a>. A change of basis separates its four residue classes. A common collective rotation puts the paired vectors in the reversal convention above. Refining the remaining coordinates yields the certified algebraic root.</p><p>The refined projector differs from the rotated numerical source by approximately '''+tex(r'3.76\times10^{-8}')+''' in Frobenius norm. This comparison associates the construction with the supplied decimals; the exact polynomial certificate establishes existence independently.</p><h2>Majorana representations</h2><p>Exact rational interval estimates and disjoint Rouché disks certify the multiplicities of all four constellations:</p>'''+tex(r'\lambda(u_1)=\lambda(u_4)=(3,1^{16}),\qquad\lambda(u_2)=\lambda(u_3)=(2,1^{17}).',True)+'''<p>The sixteen roots of the reduced quartics are certified simple and nonzero. Numerical sphere coordinates reconstruct the state rays to within '''+tex(r'1.2\times10^{-15}')+'''. Each constellation describes one chosen basis vector.</p><h2>Proof and reproducibility</h2><div class="downloads">'''
 for name,label in [('basis.json','Analytical basis'),('proof.tex','Complete LaTeX proof'),('certificate.json','Rational existence certificate'),('verify.py','Primary exact verifier'),('verification.json','Primary verification report'),('verify_independently.py','Independent verifier'),('independent-verification.json','Independent report'),('verify_geometry.py','Majorana verifier'),('geometry.json','Majorana coordinates and root disks'),('geometry-verification.json','Geometry report')]:body+='<a href="'+name+'">'+label+' ↓</a>'
 body+='''</div></section><footer><p>Anticoherent subspaces · 30 October 2026</p><a href="../../index.html#n=19&amp;t=2&amp;subspace=algebraic-n19-k4-t2">Return to the catalogue ↗</a></footer>'''
 head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nineteen qubits: an optimal algebraic second-order AC subspace</title><link rel="stylesheet" href="../../vendor/katex/katex.min.css"><script defer src="../../vendor/katex/katex.min.js"></script><style>'+css+'</style><script>document.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("[data-tex]").forEach(el=>{if(window.katex)el.innerHTML=katex.renderToString(el.dataset.tex,{displayMode:el.dataset.display==="true",throwOnError:false,strict:"ignore",trust:false});}));</script></head><body><main>'
 (HERE/'index.html').write_text(head+body+'</main></body></html>\n')
if __name__=='__main__':main()
